/// Non-primary member count (lane-priority order).
pub const N_DY: usize = 2;
/// The block-uniform boundary tuple of a non-primary member.
#[derive(Clone, Copy, PartialEq, Eq)]
pub struct DyTuple {
    pub c38: bool,
    pub c39: P8,
    pub c84: P8,
    pub c87: P8,
}

impl DyTuple {
    /// Raw-bits collapse key (BTreeMap-friendly).
    pub fn key(&self) -> [u32; 4] {
        [
            self.c38 as u32,
            self.c39.as_raw_u32(),
            self.c84.as_raw_u32(),
            self.c87.as_raw_u32(),
        ]
    }
}

/// Per-lane extension of the collapse key: reachable boundary cells
/// of the non-primary members whose per-lane value IS the primary's
/// own out column (proven the same fused node at emission time), so
/// the executor reads them straight out of KOut/KOutShared.
pub const N_DY_VARY: usize = 2;
#[allow(unused_variables)]
pub fn dy_vary_key(sh: &KOutShared, kv: &KOut, lane: usize) -> [u64; N_DY_VARY] {
    [
        kv.c20[lane].as_raw_u32() as u64,
        (kv.c41.val >> lane & 1) as u64 | ((kv.c41.known >> lane & 1) as u64) << 1,
    ]
}

/// Per-(config, variant) coverage of the non-primary members.
pub struct Dy {
    /// Lanes covered by member i+1 (valid, primary-deopt, own-
    /// coverage clear, earlier members excluded).
    pub covered: [u16; N_DY],
    pub tuples: [DyTuple; N_DY],
}

