/// Variant-independent key cells (sh/chunk sources): the shared base
/// of the support-factored pre-dedup key. ADDS into h1/h2.
#[allow(unused_variables)]
pub fn row_keys_base(chunk: &Rt2, lo: usize, n: usize, sh: &KOutShared, plan: &KeyPlan, h1: &mut [u64; W], h2: &mut [u64; W]) {
    // cell 84 (P8)
    if plan.rem & (1 << 2) == 0 {
        let c1 = 0x5bf0_3635u64 ^ (84u64).wrapping_mul(0x9e37_79b9_7f4a_7c15);
        let c2 = 0x27d4_eb2fu64 ^ (84u64).wrapping_mul(0x9e37_79b9_7f4a_7c15);
        for i in 0..W {
            let v = sh.c84;
            let v = if plan.det & (1 << 2) != 0 && v < P8::from_raw(0i32) { P8::from_raw(0i32) } else { v };
            let code = 1u64 << 56 | v.to_bits() as u64;
            h1[i] = h1[i].wrapping_add(mix64(c1 ^ code));
            h2[i] = h2[i].wrapping_add(mix64(c2 ^ code));
        }
    }
    // cell 254 (ZN)
    if plan.rem & (1 << 10) == 0 {
        let c1 = 0x5bf0_3635u64 ^ (254u64).wrapping_mul(0x9e37_79b9_7f4a_7c15);
        let c2 = 0x27d4_eb2fu64 ^ (254u64).wrapping_mul(0x9e37_79b9_7f4a_7c15);
        for i in 0..W {
            let v = sh.c254[i];
            let v = if plan.det & (1 << 10) != 0 && v < P8::from_raw(0i32) { P8::from_raw(0i32) } else { v };
            let code = 1u64 << 56 | v.to_bits() as u64;
            h1[i] = h1[i].wrapping_add(mix64(c1 ^ code));
            h2[i] = h2[i].wrapping_add(mix64(c2 ^ code));
        }
    }
    // cell 278 (ZI)
    if plan.rem & (1 << 16) == 0 {
        assert!(plan.det & (1 << 16) == 0, "det clamp on non-numeric cell 278");
        for i in 0..W {
            let v = AV::Ival(sh.c278.lo[i], sh.c278.hi[i]);
            h1[i] = h1[i].wrapping_add(cell_mix(278u64, v, 0x5bf0_3635));
            h2[i] = h2[i].wrapping_add(cell_mix(278u64, v, 0x27d4_eb2f));
        }
    }
    // cell 279 (ZI)
    if plan.rem & (1 << 17) == 0 {
        assert!(plan.det & (1 << 17) == 0, "det clamp on non-numeric cell 279");
        for i in 0..W {
            let v = AV::Ival(sh.c279.lo[i], sh.c279.hi[i]);
            h1[i] = h1[i].wrapping_add(cell_mix(279u64, v, 0x5bf0_3635));
            h2[i] = h2[i].wrapping_add(cell_mix(279u64, v, 0x27d4_eb2f));
        }
    }
}

/// Button-bit support of each non-full kv key-cell class, in
/// `row_keys_class` arm order.
pub const KEY_CLASS_SUPS: &[u8] = &[];
/// One class's kv cells: identical for variants agreeing on the
/// class's support, so the executor caches the result per
/// assignment. ADDS into h1/h2.
#[allow(unused_variables)]
pub fn row_keys_class(class: usize, kv: &KOut, plan: &KeyPlan, h1: &mut [u64; W], h2: &mut [u64; W]) {
    match class {
    _ => unreachable!(),
    }
}

