/// Finalize a factored key: the same final mix as `row_keys`.
pub fn row_keys_fin(h1: &[u64; W], h2: &[u64; W], keys: &mut [(u64, u64); W]) {
    for i in 0..W {
        keys[i] = (mix64(h1[i]), mix64(h2[i]));
    }
}

